DO $$
DECLARE
    fan_rec RECORD;
    avg_fmi NUMERIC;
    eps NUMERIC;
BEGIN
    RAISE NOTICE '=== Top Users Report: Idol Superfans ===';
    RAISE NOTICE '';

    FOR fan_rec IN
        SELECT f.user_registry, f.nick_label
        FROM fans f
        JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
        JOIN eventsandclub e ON m.member_reg = e.events_member_pivot
        GROUP BY f.user_registry, f.nick_label
    LOOP
        -- Calculate average FMI for this fan
        SELECT COALESCE(AVG(CAST(im.gift_metrics->>'Gift_Val_Usd' AS NUMERIC) / NULLIF(i.sess_dur_min, 0)), 0)
        INTO avg_fmi
        FROM interactions i
        JOIN jsonb_array_elements(i.gift_metrics::jsonb) AS im(gift_metrics) ON true
        WHERE i.interact_fan_pivot = fan_rec.user_registry;

        -- Actually, gift_metrics is already a JSONB object per row, not an array
        -- Let me recalculate properly
        SELECT COALESCE(AVG(CAST(i.gift_metrics->>'Gift_Val_Usd' AS NUMERIC) / NULLIF(i.sess_dur_min, 0)), 0)
        INTO avg_fmi
        FROM interactions i
        WHERE i.interact_fan_pivot = fan_rec.user_registry;

        -- Calculate EPS for this fan
        SELECT COALESCE(
            (CAST(e.evt_participation->>'On_Evt_Att' AS NUMERIC)) * 1 +
            (CAST(e.evt_participation->>'Off_Evt_Att' AS NUMERIC)) * 1.5 +
            (CAST(e.evt_participation->>'Meet_Att' AS NUMERIC)) * 2,
            0
        )
        INTO eps
        FROM eventsandclub e
        JOIN membershipandspending m ON m.member_reg = e.events_member_pivot
        WHERE m.member_fan_pivot = fan_rec.user_registry;

        -- Check if Idol Superfan: FMI > 20 AND EPS > 25
        IF avg_fmi > 20 AND eps > 25 THEN
            RAISE NOTICE 'Idol Superfan found: % (%), Avg FMI: %, Event Score: %',
                fan_rec.user_registry, fan_rec.nick_label, ROUND(avg_fmi, 2), eps;
        END IF;
    END LOOP;

    RAISE NOTICE '';
    RAISE NOTICE 'Report complete.';
END $$;

DO $$
DECLARE
    fan_rec RECORD;
    avg_fmi NUMERIC;
    eps NUMERIC;
BEGIN
    RAISE NOTICE '=== Top Users Report: Idol Superfans ===';
    RAISE NOTICE '';

    FOR fan_rec IN
        SELECT f.user_registry, f.nick_label
        FROM fans f
        JOIN membershipandspending m ON f.user_registry = m.member_fan_pivot
        JOIN eventsandclub e ON m.member_reg = e.events_member_pivot
        GROUP BY f.user_registry, f.nick_label
    LOOP
        -- Calculate average FMI for this fan (Total Gift Value USD / Session Duration Minutes)
        SELECT COALESCE(AVG(CAST(i.gift_metrics->>'Gift_Val_Usd' AS NUMERIC) / NULLIF(i.sess_dur_min, 0)), 0)
        INTO avg_fmi
        FROM interactions i
        WHERE i.interact_fan_pivot = fan_rec.user_registry;

        -- Calculate EPS for this fan: (Online Events × 1) + (Offline Events × 1.5) + (Meet-and-Greets × 2)
        SELECT COALESCE(
            (CAST(e.evt_participation->>'On_Evt_Att' AS NUMERIC)) * 1 +
            (CAST(e.evt_participation->>'Off_Evt_Att' AS NUMERIC)) * 1.5 +
            (CAST(e.evt_participation->>'Meet_Att' AS NUMERIC)) * 2,
            0
        )
        INTO eps
        FROM eventsandclub e
        JOIN membershipandspending m ON m.member_reg = e.events_member_pivot
        WHERE m.member_fan_pivot = fan_rec.user_registry;

        -- Check if Idol Superfan: Whale Fan (FMI > 20) AND Event Enthusiast (EPS > 25)
        IF avg_fmi > 20 AND eps > 25 THEN
            RAISE NOTICE 'Idol Superfan found: % (%), Avg FMI: %, Event Score: %',
                fan_rec.user_registry, fan_rec.nick_label, ROUND(avg_fmi, 2), eps;
        END IF;
    END LOOP;

    RAISE NOTICE '';
    RAISE NOTICE 'Report complete.';
END $$;

